function totalAnt() { var l = linhasAnt(), v = num($("#a-ant-valor").value) || 0; $("#a-ant-total").innerHTML = l.length + ' sessão(ões) × R$ ' + brl(v) + ' = <b>R$ ' + brl(l.length * v) + '</b> recebidos em ' + esc($("#a-ant-datapag").value || '—'); }
